begin;
create extension if not exists pgcrypto;

alter table if exists public.angelcare360_payroll_periods
 add column if not exists input_cutoff_at timestamptz,
 add column if not exists finalized_at timestamptz,
 add column if not exists finalized_by uuid references public.app_users(id) on delete set null,
 add column if not exists reopened_at timestamptz,
 add column if not exists reopened_by uuid references public.app_users(id) on delete set null,
 add column if not exists reopen_reason text;

alter table if exists public.angelcare360_payroll_periods drop constraint if exists angelcare360_payroll_periods_status_check;
alter table if exists public.angelcare360_payroll_periods add constraint angelcare360_payroll_periods_status_check check(status in('draft','planned','open','inputs_collecting','input_cutoff','ready','calculating','calculated','review','validated','approved','finalized','payment_processing','paid','reconciled','closed','cancelled','archived'));

create table if not exists public.angelcare360_workforce_employments(
 id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,employee_number text not null,institution_id uuid references public.angelcare360_schools(id) on delete set null,department text,position_title text,employment_category text not null default 'employee',starts_on date not null,ends_on date,payroll_eligible boolean not null default true,status text not null default 'draft',effective_state_at timestamptz,transition_reason text,payment_method text,payment_account_masked text,metadata_json jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,employee_number)
);
create index if not exists idx_ac360_workforce_employment_staff on public.angelcare360_workforce_employments(school_id,staff_id,status);
create table if not exists public.angelcare360_workforce_employment_events(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,employment_id uuid not null references public.angelcare360_workforce_employments(id) on delete cascade,from_state text,to_state text not null,reason text,effective_at timestamptz not null,execution_id uuid,actor_user_id uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.angelcare360_workforce_contract_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,employment_id uuid not null references public.angelcare360_workforce_employments(id) on delete cascade,contract_number text not null,contract_type text not null,starts_on date not null,ends_on date,weekly_hours numeric(8,2),payroll_frequency text not null default 'monthly',status text not null default 'draft',version_number integer not null default 1,supersedes_version_id uuid references public.angelcare360_workforce_contract_versions(id) on delete set null,terms_json jsonb not null default '{}'::jsonb,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,contract_number,version_number));
create table if not exists public.angelcare360_workforce_assignments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,employment_id uuid not null references public.angelcare360_workforce_employments(id) on delete cascade,assignment_type text not null default 'primary',institution_id uuid references public.angelcare360_schools(id) on delete set null,department text,position_title text,cost_center text,allocation_percent numeric(7,4) not null default 100,effective_from date not null,effective_to date,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,check(allocation_percent>0 and allocation_percent<=100));

create table if not exists public.angelcare360_compensation_package_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,code text not null,name text not null,version_number integer not null default 1,currency text not null default 'MAD',base_salary_minor bigint not null default 0,status text not null default 'draft',effective_from date not null,effective_to date,configuration_json jsonb not null default '{}'::jsonb,supersedes_version_id uuid references public.angelcare360_compensation_package_versions(id) on delete set null,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,superseded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,code,version_number));
create table if not exists public.angelcare360_workforce_compensation_assignments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,employment_id uuid not null references public.angelcare360_workforce_employments(id) on delete cascade,compensation_package_version_id uuid not null references public.angelcare360_compensation_package_versions(id) on delete restrict,effective_from date not null,effective_to date,status text not null default 'active',reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null);
create index if not exists idx_ac360_comp_assignment_effective on public.angelcare360_workforce_compensation_assignments(school_id,employment_id,status,effective_from,effective_to);

create table if not exists public.angelcare360_payroll_policy_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,code text not null,name text not null,version_number integer not null default 1,status text not null default 'draft',effective_from date not null,effective_to date,configuration_json jsonb not null default '{}'::jsonb,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,supersedes_version_id uuid references public.angelcare360_payroll_policy_versions(id) on delete set null,superseded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,code,version_number));
create table if not exists public.angelcare360_payroll_component_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,code text not null,name text not null,version_number integer not null default 1,status text not null default 'draft',effective_from date not null,effective_to date,configuration_json jsonb not null default '{}'::jsonb,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,supersedes_version_id uuid references public.angelcare360_payroll_component_versions(id) on delete set null,superseded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,code,version_number));
create table if not exists public.angelcare360_payroll_calendar_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,code text not null,name text not null,version_number integer not null default 1,status text not null default 'draft',effective_from date not null,effective_to date,configuration_json jsonb not null default '{}'::jsonb,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,supersedes_version_id uuid references public.angelcare360_payroll_calendar_versions(id) on delete set null,superseded_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,code,version_number));

create table if not exists public.angelcare360_payroll_input_revisions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payroll_period_id uuid not null references public.angelcare360_payroll_periods(id) on delete cascade,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,component_code text not null,input_type text not null,amount_minor bigint not null default 0,quantity numeric(14,4) not null default 1,currency text not null default 'MAD',source_type text not null,source_id uuid,evidence_json jsonb not null default '{}'::jsonb,status text not null default 'submitted',idempotency_key text not null,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,idempotency_key));
create index if not exists idx_ac360_payroll_input_period_staff on public.angelcare360_payroll_input_revisions(school_id,payroll_period_id,staff_id,status);
create table if not exists public.angelcare360_payroll_advances_sovereign(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,advance_code text not null,principal_minor bigint not null,recovered_minor bigint not null default 0,remaining_minor bigint not null,installment_minor bigint not null,installment_count integer not null,recovery_start_period_id uuid references public.angelcare360_payroll_periods(id) on delete set null,status text not null default 'requested',reason text,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,disbursed_by uuid references public.app_users(id) on delete set null,disbursed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,advance_code),check(principal_minor=recovered_minor+remaining_minor));

create table if not exists public.angelcare360_payroll_run_executions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payroll_period_id uuid not null references public.angelcare360_payroll_periods(id) on delete cascade,run_code text not null,run_type text not null default 'regular',status text not null default 'draft',input_hash text not null,input_snapshot jsonb not null default '{}'::jsonb,totals_json jsonb not null default '{}'::jsonb,idempotency_key text not null,started_by uuid references public.app_users(id) on delete set null,started_at timestamptz,completed_at timestamptz,validated_by uuid references public.app_users(id) on delete set null,validated_at timestamptz,approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,finalized_by uuid references public.app_users(id) on delete set null,finalized_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,run_code),unique(school_id,idempotency_key));
create table if not exists public.angelcare360_payroll_employee_results(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payroll_run_id uuid not null references public.angelcare360_payroll_run_executions(id) on delete cascade,payroll_period_id uuid not null references public.angelcare360_payroll_periods(id) on delete cascade,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,employment_id uuid references public.angelcare360_workforce_employments(id) on delete set null,compensation_assignment_id uuid references public.angelcare360_workforce_compensation_assignments(id) on delete set null,base_minor bigint not null default 0,earnings_minor bigint not null default 0,gross_minor bigint not null default 0,employee_contributions_minor bigint not null default 0,employer_contributions_minor bigint not null default 0,deductions_minor bigint not null default 0,reimbursements_minor bigint not null default 0,net_payable_minor bigint not null default 0,employer_cost_minor bigint not null default 0,status text not null default 'calculated',calculation_json jsonb not null default '{}'::jsonb,calculation_hash text not null,finalized_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(payroll_run_id,staff_id),check(gross_minor=base_minor+earnings_minor),check(net_payable_minor=gross_minor+reimbursements_minor-employee_contributions_minor-deductions_minor),check(employer_cost_minor=gross_minor+employer_contributions_minor+reimbursements_minor));
create index if not exists idx_ac360_payroll_result_staff on public.angelcare360_payroll_employee_results(school_id,staff_id,payroll_period_id);

create table if not exists public.angelcare360_payroll_payslip_versions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payroll_run_id uuid not null references public.angelcare360_payroll_run_executions(id) on delete cascade,payroll_employee_result_id uuid not null references public.angelcare360_payroll_employee_results(id) on delete cascade,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,version_number integer not null,version_code text not null,source_signature text not null,document_path text not null,status text not null default 'generated',supersedes_version_id uuid references public.angelcare360_payroll_payslip_versions(id) on delete set null,generated_by uuid references public.app_users(id) on delete set null,generated_at timestamptz,published_by uuid references public.app_users(id) on delete set null,published_at timestamptz,created_at timestamptz not null default now(),unique(school_id,version_code),unique(payroll_employee_result_id,source_signature));
create table if not exists public.angelcare360_payroll_payment_batches(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payroll_run_id uuid not null references public.angelcare360_payroll_run_executions(id) on delete restrict,batch_code text not null,payment_method text not null,currency text not null default 'MAD',payment_date date not null,total_minor bigint not null,status text not null default 'draft',approved_by uuid references public.app_users(id) on delete set null,approved_at timestamptz,reconciled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,batch_code));
create table if not exists public.angelcare360_payroll_payment_items(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payment_batch_id uuid not null references public.angelcare360_payroll_payment_batches(id) on delete cascade,payroll_employee_result_id uuid not null references public.angelcare360_payroll_employee_results(id) on delete restrict,staff_id uuid not null references public.angelcare360_staff(id) on delete restrict,amount_minor bigint not null,status text not null default 'pending',provider_reference text,paid_at timestamptz,failure_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(payment_batch_id,payroll_employee_result_id));
create table if not exists public.angelcare360_payroll_reconciliation_sessions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,payment_batch_id uuid not null references public.angelcare360_payroll_payment_batches(id) on delete restrict,status text not null,expected_minor bigint not null,paid_minor bigint not null,failed_count integer not null default 0,pending_count integer not null default 0,resolved_by uuid references public.app_users(id) on delete set null,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null);

create table if not exists public.angelcare360_payroll_sovereign_executions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,operation_key text not null,entity_id uuid,idempotency_key text not null,state text not null default 'requested',request_payload jsonb not null default '{}'::jsonb,result_payload jsonb not null default '{}'::jsonb,reason text,last_error text,requested_by uuid references public.app_users(id) on delete set null,requested_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,unique(school_id,idempotency_key));
create table if not exists public.angelcare360_payroll_offcycle_runs(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.angelcare360_schools(id) on delete cascade,code text not null,name text not null,version_number integer not null default 1,status text not null,effective_from date not null,effective_to date,configuration_json jsonb not null default '{}'::jsonb,published_by uuid references public.app_users(id),published_at timestamptz,supersedes_version_id uuid references public.angelcare360_payroll_offcycle_runs(id),superseded_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),created_by uuid references public.app_users(id),updated_by uuid references public.app_users(id),unique(school_id,code,version_number));
create table if not exists public.angelcare360_payroll_final_settlement_runs(like public.angelcare360_payroll_offcycle_runs including all);
create table if not exists public.angelcare360_payroll_controlled_exports(like public.angelcare360_payroll_offcycle_runs including all);

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('angelcare360-payroll-documents','angelcare360-payroll-documents',false,20971520,array['application/pdf','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false;

-- Tenant RLS and server-authority write posture
DO $$ declare t text; begin foreach t in array ARRAY['angelcare360_workforce_employments','angelcare360_workforce_employment_events','angelcare360_workforce_contract_versions','angelcare360_workforce_assignments','angelcare360_compensation_package_versions','angelcare360_workforce_compensation_assignments','angelcare360_payroll_policy_versions','angelcare360_payroll_component_versions','angelcare360_payroll_calendar_versions','angelcare360_payroll_input_revisions','angelcare360_payroll_advances_sovereign','angelcare360_payroll_run_executions','angelcare360_payroll_employee_results','angelcare360_payroll_payslip_versions','angelcare360_payroll_payment_batches','angelcare360_payroll_payment_items','angelcare360_payroll_reconciliation_sessions','angelcare360_payroll_sovereign_executions','angelcare360_payroll_offcycle_runs','angelcare360_payroll_final_settlement_runs','angelcare360_payroll_controlled_exports'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke insert,update,delete on public.%I from anon,authenticated',t); end loop; end $$;

commit;
